import get from 'lodash/get';
import isArray from 'lodash/isArray';

import { isObject } from '../../../../utils/objects';
import { CREATOR_FIELDS } from '../../../constants/attributes';
import { getInitialDataPathUsingTempKeys } from '../../../utils/paths';

import type { FormattedComponentLayout, FormattedContentTypeLayout } from '../../../utils/layouts';
import type { RelationData } from '../reducer';
import type { Attribute, Common, Entity } from '@strapi/types';

const cleanData = (
  {
    browserState, // the modifiedData from REDUX
    serverState, // the initialData from REDUX
  }: { browserState: Record<string, any>; serverState: Record<string, any> },
  currentSchema: FormattedContentTypeLayout,
  componentsSchema: Record<string, FormattedComponentLayout>
) => {
  const rootServerState = serverState;
  const rootBrowserState = browserState;

  const recursiveCleanData = (
    browserState: Record<string, any>,
    serverState: Record<string, any>,
    schema: FormattedContentTypeLayout | FormattedComponentLayout,
    pathToParent: string // the path to the parent of the current entry
  ) => {
    return Object.keys(browserState).reduce<Record<string, any>>((acc, current) => {
      // Creator attributes can be safely ignored because they are handle on the backend
      if (CREATOR_FIELDS.includes(current)) {
        return acc;
      }

      const path = pathToParent ? `${pathToParent}.${current}` : current;
      const attribute = schema.attributes[current] ?? {};
      const { type } = attribute;

      // This is the field value
      const value = get(browserState, current);
      const oldValue = get(serverState, current);
      let cleanedData;

      switch (type) {
        case 'json':
          cleanedData = JSON.parse(value);
          break;
        case 'time': {
          cleanedData = value;

          // FIXME
          if (value && value.split(':').length < 3) {
            cleanedData = `${value}:00`;
          }

          break;
        }
        case 'media':
          if (attribute.multiple === true) {
            cleanedData = value ? value.filter((file: unknown) => !(file instanceof File)) : null;
          } else {
            cleanedData = get(value, 0) instanceof File ? null : get(value, 'id', null);
          }
          break;
        case 'component':
          if (attribute.repeatable) {
            cleanedData = value
              ? (value as Attribute.GetValue<Attribute.Component<Common.UID.Component, true>>).map(
                  (data, index) => {
                    const subCleanedData = recursiveCleanData(
                      data,
                      (oldValue ?? [])[index],
                      componentsSchema[attribute.component],
                      `${path}.${index}`
                    );

                    return subCleanedData;
                  }
                )
              : value;
          } else {
            cleanedData = value
              ? recursiveCleanData(value, oldValue, componentsSchema[attribute.component], path)
              : value;
          }

          break;

        case 'relation': {
          const trueInitialDataPath = getInitialDataPathUsingTempKeys(
            rootServerState,
            rootBrowserState
          )(path);

          /**
           * Because of how repeatable components work when you dig into them the server
           * will have no object to compare too therefore no relation array will be setup
           * because the component has not been initialized, therefore we can safely assume
           * it needs to be added and provide a default empty array.
           */
          const actualOldValue = get(rootServerState, trueInitialDataPath, []) as RelationData[];

          interface RelationApiData extends Pick<RelationData, 'id'> {
            position:
              | {
                  before: Entity.ID;
                  end?: never;
                }
              | {
                  before?: never;
                  end: boolean;
                };
          }

          /**
           * Instead of the full relation object, we only want to send its ID
           *  connectedRelations are the items that are in the browserState
           * array but not in the serverState
           */
          const connectedRelations = (value as RelationData[]).reduce<RelationApiData[]>(
            (acc, relation, currentIndex, array) => {
              const relationOnServer = actualOldValue.find(
                (oldRelation) => oldRelation.id === relation.id
              );

              const relationInFront = array[currentIndex + 1];

              if (!relationOnServer || relationOnServer.__temp_key__ !== relation.__temp_key__) {
                const position = relationInFront ? { before: relationInFront.id } : { end: true };

                return [...acc, { id: relation.id, position }];
              }

              return acc;
            },
            []
          );

          /**
           * disconnectedRelations are the items that are in the serverState but
           * are no longer in the browserState
           */
          const disconnectedRelations = actualOldValue.reduce<Omit<RelationApiData, 'position'>[]>(
            (acc, relation) => {
              if (
                !(value as RelationData[]).find((newRelation) => newRelation.id === relation.id)
              ) {
                return [...acc, { id: relation.id }];
              }

              return acc;
            },
            []
          );

          cleanedData = {
            disconnect: disconnectedRelations,
            /**
             * Reverse the array because the API sequentially goes through the list
             * so in an instance where you add two to the end it would fail because index0
             * would want to attach itself to index1 which doesn't exist yet.
             */
            connect: connectedRelations.reverse(),
          };

          break;
        }

        case 'dynamiczone':
          cleanedData = (value as Attribute.GetValue<Attribute.DynamicZone>).map(
            (componentData, index) => {
              const subCleanedData = recursiveCleanData(
                componentData,
                (oldValue ?? [])[index],
                componentsSchema[componentData.__component],
                `${path}.${index}`
              );

              return subCleanedData;
            }
          );
          break;
        default:
          cleanedData = helperCleanData(value, 'id');
      }

      acc[current] = cleanedData;

      return acc;
    }, {});
  };

  return recursiveCleanData(browserState, serverState, currentSchema, '');
};

// TODO: check which parts are still needed: I suspect the
// isArray part can go away, but I'm not sure what could send
// an object; in case both can go away we might be able to get
// rid of the whole helper
const helperCleanData = (value: any, key: string) => {
  if (isArray(value)) {
    return value.map((obj) => (obj[key] ? obj[key] : obj));
  }
  if (isObject(value)) {
    return value[key as keyof typeof value];
  }

  return value;
};

export { cleanData };
